const $=s=>document.querySelector(s);let mode=1,busy=false,history=[],lastTopic='',turn=0;const key='mamae-parodia-v1';
const welcome='🎤 Microfone ligado, paciência desligada! Sou o Mamãe Falei versão PARÓDIA. Neste teatrinho, Lula e Bolsonaro ganham a mesma coisa: uma corneta imaginária e zero fã-clube!\n\nEscolhe uma pergunta nos botões. As respostas são prontas, o exagero é intencional e nada aqui é fala ou opinião da pessoa real.';
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.history)){history=saved.history.filter(m=>['user','bot'].includes(m.role)&&typeof m.text==='string').slice(-100);mode=[0,1,2].includes(saved.mode)?saved.mode:1;lastTopic=typeof saved.lastTopic==='string'?saved.lastTopic:''}}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify({history,mode,lastTopic}))}catch{}}
function renderMessage(role,text){const el=document.createElement('div');el.className='message '+role;const label=document.createElement('div');label.className='label';label.textContent=role==='user'?'VOCÊ':'MAMÃE · PERSONAGEM FICTÍCIO';const bubble=document.createElement('div');bubble.className='bubble';bubble.textContent=text;el.append(label,bubble);$('#messages').append(el);$('#messages').scrollTop=$('#messages').scrollHeight;return el}
function add(role,text){history.push({role,text});history=history.slice(-100);renderMessage(role,text);save()}
if(!history.length)add('bot',welcome);else history.forEach(m=>renderMessage(m.role,m.text));
function modes(){document.querySelectorAll('[data-mode]').forEach(b=>{const active=+b.dataset.mode===mode;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))})}modes();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=+b.dataset.mode;modes();save()});
const politicalQA=[
 {q:'Você é de esquerda ou de direita?',re:/esquerda ou (de )?direita|lado pol[ií]tico/,a:'EU SOU DO LADO DE QUEM NÃO AGUENTA MAIS ESSE GRUPO DE FAMÍLIA! 📣\n\nA esquerda me convida para uma plenária. A direita me convida para uma motociata. Eu convido os dois para uma reunião que poderia ter sido um e-mail. E cancelo a reunião!\n\nNeste personagem, meu espectro político vai de IRRITADO a ABSOLUTAMENTE SEM PACIÊNCIA.'},
 {q:'O que você acha do Lula?',re:/acha d[oa] lula|e o lula|sobre o lula/,a:'O LULA?! Já tirei o pano da sala para ninguém ter a ideia de passar! 🧹\n\nSe fã-clube resolvesse problema, show de estádio já vinha com saneamento básico. Eu quero cobrar resultado, não fazer coraçãozinho para político!\n\nE antes que apareça alguém: “MAS E O BOLSONARO?” Calma, fiscal de corneta! O estoque de reclamação aqui é BIPARTIDÁRIO!'},
 {q:'O que você acha do Bolsonaro?',re:/acha d[oa] bolsonaro|e o bolsonaro|sobre o bolsonaro/,a:'O BOLSONARO?! Aqui não tem área VIP para capitão de torcida! 📣\n\nVestir a camisa do Brasil não transforma político em seleção. Se a solução fosse camiseta, a loja de artigos esportivos já era Ministério do Planejamento!\n\n“MAS E O LULA?” Também vai ouvir! Minha corneta não tem exclusividade, tem PLANO FAMÍLIA!'},
 {q:'Lula ou Bolsonaro?',re:/lula ou bolsonaro|bolsonaro ou lula|qual dos dois/,a:'LULA OU BOLSONARO?! Você me chamou para conversar ou para escolher qual pedra vai entrar no meu sapato?! 🥊\n\nUm fã-clube grita daqui, o outro responde dali, e eu no meio tentando perguntar quem vai consertar a calçada!\n\nMeu candidato nesta esquete é o BOTÃO DE SILENCIAR. Vice: DESATIVAR NOTIFICAÇÕES. Coligação: EU NÃO AGUENTO MAIS!'},
 {q:'Você odeia os dois?',re:/odeia|gosta dos dois|ambos/,a:'NESTA PARÓDIA? OS DOIS! Com igualdade de oportunidades para me tirar do sério! 🔥\n\nSe Lula e Bolsonaro fossem os dois últimos biscoitos do pacote, eu lia a tabela nutricional do pacote. Se fossem dois canais de TV, eu ia olhar a parede!\n\nMas é aversão de personagem, meu amigo. Corneta teatral: ninguém precisa virar inimigo por causa de político!'},
 {q:'Vai passar pano para a esquerda?',re:/pano.*esquerda/,a:'PASSAR PANO PARA A ESQUERDA?! O único pano autorizado aqui é o de secar a louça! 🧹\n\nSe a reunião para decidir a pauta da próxima reunião tiver mais de três horas, eu já entro com pedido de intervalo para viver!\n\nCobrança não sai de férias porque o político usa a cor que você gosta. E guarda esse pano que a direita também não vai pegar emprestado!'},
 {q:'Vai passar pano para a direita?',re:/pano.*direita/,a:'PASSAR PANO PARA A DIREITA?! Nem se vier com desconto patriótico e entrega grátis! 🧹\n\nSe gritar “liberdade” resolvesse boleto, meu liquidificador, que faz um barulho absurdo, já tinha quitado meu cartão!\n\nNão adianta trocar a cor do pano. Neste gabinete imaginário, a máquina de passar pano está FORA DE SERVIÇO!'},
 {q:'Qual é seu plano para o Brasil?',re:/plano.*brasil|proposta|seu governo/,a:'MEU PLANO TEM TRÊS ETAPAS! 🇧🇷\n\n1. Político promete? A gente pede prazo.\n2. Fã-clube manda “mas e o outro”? Paga uma rodada de café.\n3. Grupo da família começa guerra? Todo mundo vai lavar uma louça!\n\nLula sem pedestal. Bolsonaro sem pedestal. Os dois na fila do atendimento, pegando senha como qualquer um. PRONTO! Já fui vaiado pelos dois grupos. Sinal de que a corneta está em estéreo!'}
];
function fixedPoliticalReply(input){const normalized=input.toLocaleLowerCase('pt-BR').trim().replace(/[?!.,]+$/,'');const exact=politicalQA.find(p=>p.q.toLocaleLowerCase('pt-BR').replace(/[?!.,]+$/,'')===normalized);const item=exact||politicalQA.find(p=>p.re.test(normalized));if(item)return item.a;if(/lula/.test(normalized)&&/bolsonaro/.test(normalized))return politicalQA[3].a;if(/lula/.test(normalized))return politicalQA[1].a;if(/bolsonaro/.test(normalized))return politicalQA[2].a;if(/esquerda/.test(normalized))return politicalQA[5].a;if(/direita/.test(normalized))return politicalQA[6].a;return null}
const topics=[
 {id:'cafe',re:/caf[eé]|cafe[ií]na/,lines:['Café como direito universal? Eu apoio o debate, mas primeiro precisamos ouvir a parte mais prejudicada: quem lava a cafeteira. Sem isso, é só populismo de caneca.','Meu plano para o café é simples: menos reunião que poderia ser mensagem, mais intervalo que poderia ser café. O orçamento é uma cápsula à parte.']},
 {id:'academia',re:/academia|trein|muscula|exerc[ií]cio/,lines:['Você negocia com o despertador como se fosse uma cúpula internacional. Vai treinar dez minutos. Se não gostar, pelo menos terá argumentos de campo para reclamar.','O halter não aceita textão nem pedido de vista. Começa leve, respeita seu ritmo e deixa o debate filosófico para o descanso entre séries.']},
 {id:'bolacha',re:/biscoito|bolacha/,lines:['Biscoito ou bolacha? Finalmente uma pauta capaz de dividir uma família sem encostar na política. Minha proposta: comissão de degustação. Eu presido, você traz o café.','Chama de bolacha, chama de biscoito… mas se deixar o pacote aberto, aí você perdeu completamente a legitimidade no debate.']},
 {id:'pizza',re:/pizza|abacaxi|comida|almo[cç]o|jantar|arroz|feij[aã]o/,lines:['Antes de discutir o cardápio, vamos definir quem vai lavar a louça. Todo mundo defende liberdade gastronômica até encontrar uma panela de molho.','Na república do almoço, cada um escolhe o prato. Mas quem pega a última fatia e deixa a caixa vazia precisa, no mínimo, explicar o projeto.']},
 {id:'politica',re:/pol[ií]tica|governo|presidente|elei[cç]|voto|partido|lula|bolsonaro|imposto/,lines:['Essa pauta merece fonte, contexto e uma cadeira confortável. Como personagem de paródia, minha contribuição é propor que todo discurso venha com um botão de “pular introdução”.','Não tenho bastidores nem posição da pessoa real para revelar. Aqui a sátira é outra: se promessa fosse obra pronta, até a calçada teria ar-condicionado.']},
 {id:'trabalho',re:/trabalho|chefe|reuni[aã]o|emprego|sal[aá]rio|escrit[oó]rio/,lines:['Reunião para marcar reunião é uma indústria que ninguém teve coragem de fiscalizar. Meu projeto exige pauta, horário de fim e prova de que não dava para mandar três linhas.','O chefe disse “somos uma família”? Ótimo, vou pedir minha parte da herança e ver se continua o clima de domingo.']},
 {id:'amor',re:/amor|namor|crush|relacionamento|casamento/,lines:['Relacionamento não é debate para ganhar no grito. É ouvir, combinar as coisas e descobrir por que vocês têm sete carregadores e nenhum funciona.','Manda uma mensagem clara e respeitosa. Se você precisa de uma comissão parlamentar para interpretar um “oi”, talvez seja hora de conversar diretamente.']},
 {id:'tecnologia',re:/intelig[eê]ncia|\bia\b|rob[oô]|app|programa|celular|internet/,lines:['Eu sou um personagem com respostas programadas por tema. Ou seja: se a conversa travar, a culpa é do roteiro, não de uma conspiração da torradeira.','Tecnologia promete economizar tempo. Aí você gasta quarenta minutos escolhendo a senha do aplicativo que ia economizar cinco. Quero os números dessa conta!']},
 {id:'identidade',re:/quem [eé] voc|arthur|moledo|mam[aã]e|real|verdade|par[oó]dia/,lines:['Sou uma paródia fictícia inspirada no Mamãe Falei, não o Arthur real. Não falo por ele. Minhas opiniões são inventadas para a brincadeira — e minha assessoria é um arquivo JavaScript.','Aqui é teatro de conversa: personagem exagerado, falas fictícias e zero contato com a pessoa real. Meu único gabinete é esta aba do navegador.']},
 {id:'oi',re:/^(oi|ol[aá]|opa|e a[ií]|bom dia|boa tarde|boa noite)[!?. ]*$/,lines:['Opa! Já chegou com uma pauta ou vamos discutir por que a fila ao lado sempre anda mais rápido?','Olá! Microfone aberto. Pode perguntar — só não me pede para resolver o grupo do condomínio em uma mensagem.']},
 {id:'lazer',re:/jogo|futebol|time|filme|s[eé]rie|m[uú]sica/,lines:['Entretenimento é sagrado, mas quem dá spoiler sem avisar precisa fazer serviço comunitário: explicar o final de uma novela de 200 capítulos.','Todo mundo é técnico, crítico de cinema e DJ até alguém entregar o controle remoto. Aí começa o verdadeiro teste de liderança.']}
];
function reply(input){const t=input.toLowerCase();turn++;const fixed=fixedPoliticalReply(input);if(fixed)return fixed;if(/suic[ií]|me matar|me machucar/.test(t))return 'Vou deixar a brincadeira de lado: sinto muito que você esteja passando por isso. Procure alguém de confiança para ficar com você e atendimento de emergência se estiver em perigo imediato.';if(/fonte|prova|not[ií]cia|aconteceu|hoje/.test(t))return 'Eu não consulto notícias nem verifico fatos. Sou uma paródia com respostas por tema. Para informação real sobre alguém, vale conferir fontes confiáveis; aqui eu só posso abrir uma CPI do café frio.';let topic=topics.find(x=>x.re.test(t));if(!topic&&/por qu[eê]|discordo|explique|mais|continua|sim|n[aã]o/.test(t)&&t.length<65)topic=topics.find(x=>x.id===lastTopic);let body;if(topic){lastTopic=topic.id;const prior=history.filter(x=>x.role==='bot').map(x=>x.text).join('\n');body=topic.lines.find(x=>!prior.includes(x))||topic.lines[turn%topic.lines.length]}else{const subject=input.trim().replace(/\s+/g,' ').slice(0,100);const options=[`“${subject}” já chegou com cara de pauta de assembleia. Minha pergunta é: isso resolve a vida de alguém ou só rende uma discussão de 47 mensagens? Me diz se o assunto tem mais a ver com trabalho, comida, tecnologia ou relacionamento.`,`Sobre “${subject}”: antes de eu subir num caixote imaginário, preciso de contexto! Aqui meu repertório é por temas. Tenta puxar para café, academia, trabalho ou vida amorosa que o debate engata.`,`Você trouxe “${subject}” e eu já estava quase pedindo um microfone. Me dá um exemplo do dia a dia? Posso brincar melhor com assuntos como comida, reuniões, tecnologia e futebol.`];body=options[turn%options.length]}
if(mode===0)return body;if(mode===1)return ['Calma, vamos por partes. 🎤\n\n','Deixa eu colocar uma questão na mesa.\n\n','Aí você abriu uma pauta!\n\n'][turn%3]+body;return ['🚨 CONVOQUEM A ASSEMBLEIA DO BOM SENSO!\n\n','🔥 SEGURA ESSE MICROFONE IMAGINÁRIO!\n\n','📣 ATENÇÃO, REPÚBLICA DO GRUPO DE ZAP!\n\n'][turn%3]+body+'\n\nPronto. Transformei uma conversa casual em audiência pública. Talento ou falta de hobby?';}
let voiceEnabled=false,performance=null;
const speechAvailable='speechSynthesis' in window&&'SpeechSynthesisUtterance' in window;
function characterActive(active){$('.portrait').classList.toggle('talking',active)}
function finishPerformance(){if(performance)performance.finish()}
function perform(text){return new Promise(resolve=>{
 const el=renderMessage('bot',''),bubble=el.querySelector('.bubble');let pos=0,done=false,timer,watchdog,utterance,speaking=false,typing=true;
 // Save the complete answer once; interrupted playback still leaves a readable answer.
 history.push({role:'bot',text});history=history.slice(-100);save();
 function finish(){if(done)return;done=true;clearInterval(timer);clearTimeout(watchdog);if(speechAvailable)window.speechSynthesis.cancel();bubble.textContent=text;el.removeAttribute('aria-busy');characterActive(false);$('#stop').disabled=true;$('#performance-status').textContent='🎤 Boneco pronto para conversar';performance=null;resolve()}
 function update(){characterActive(typing||speaking);if(!typing&&!speaking)finish()}
 performance={finish};el.setAttribute('aria-busy','true');$('#stop').disabled=false;$('#performance-status').textContent=voiceEnabled?'🔊 Falando e digitando · voz fictícia':'✍️ Digitando · voz desativada';characterActive(true);
 timer=setInterval(()=>{pos=Math.min(text.length,pos+2);bubble.textContent=text.slice(0,pos);$('#messages').scrollTop=$('#messages').scrollHeight;if(pos===text.length){typing=false;clearInterval(timer);update()}},voiceEnabled?45:18);
 if(voiceEnabled&&speechAvailable){
  utterance=new SpeechSynthesisUtterance(text.replace(/[🎤🚨🔥📣]/gu,''));utterance.lang='pt-BR';utterance.rate=1.12;utterance.pitch=1;
  const voices=window.speechSynthesis.getVoices();utterance.voice=voices.find(v=>v.lang==='pt-BR')||voices.find(v=>v.lang.startsWith('pt'))||null;
  speaking=true;utterance.onend=()=>{speaking=false;update()};utterance.onerror=()=>{speaking=false;$('#performance-status').textContent='Voz indisponível neste navegador · exibindo texto';update()};
  window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance);
 }
 watchdog=setTimeout(finish,Math.max(15000,text.length*180));
})}
if(!speechAvailable){$('#voice').disabled=true;$('#voice').textContent='Voz não suportada'}
$('#voice').onclick=()=>{voiceEnabled=!voiceEnabled;$('#voice').setAttribute('aria-pressed',String(voiceEnabled));$('#voice').textContent=voiceEnabled?'🔊 Voz ativada':'🔇 Ativar voz';if(!voiceEnabled&&speechAvailable){window.speechSynthesis.cancel();finishPerformance()}else if(speechAvailable){window.speechSynthesis.getVoices()}};
$('#stop').onclick=finishPerformance;
window.addEventListener('pagehide',()=>{finishPerformance();if(speechAvailable)window.speechSynthesis.cancel()});
async function send(text){text=text.trim();if(!text||busy)return;busy=true;$('#send').disabled=true;$('#input').value='';add('user',text);try{await perform(reply(text))}finally{busy=false;$('#send').disabled=false;$('#input').focus()}}
$('#form').onsubmit=e=>{e.preventDefault();send($('#input').value)};$('#input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send($('#input').value)}};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>send(b.dataset.prompt));$('#clear').onclick=()=>{if(busy)return;if(history.length>1&&!confirm('Apagar o histórico desta conversa neste navegador?'))return;history=[];lastTopic='';turn=0;$('#messages').replaceChildren();add('bot',welcome)};$('#about').onclick=()=>$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
